import { useRef, useEffect, useState } from 'react'
import { Home } from 'lucide-react';
import { useSpeechRecognition } from './hooks/useSpeechRecognition';
import { useTranslation } from './hooks/useTranslation';
import { useAIResponse } from './hooks/useAIResponse';
import { useAIAutoReply } from './hooks/useAIAutoReply';
import { TranscriptionPanel } from './components/TranscriptionPanel';
import { SuggestionDock } from './components/SuggestionDock';
import { cn } from './lib/utils';
import { Logo } from './components/Logo';
import { LandingPage } from './components/LandingPage';

function App() {
  const [appMode, setAppMode] = useState<'live' | 'practice' | null>(null);
  const [autoReplyEnabled, setAutoReplyEnabled] = useState(true);
  const [isTalkPressed, setIsTalkPressed] = useState(false);

  const {
    isListening,
    currentInterim,
    history,
    setActiveSpeaker,
    beginUserTalk,
    endUserTalk,
    startListening,
    stopListening,
    resetTranscript,
    updateHistory,
    addUtterance,
    mode
  } = useSpeechRecognition({ sessionMode: appMode === 'practice' ? 'practice' : 'live' });

  const { translateText } = useTranslation();
  const { suggestions, isLoading, generateSuggestions, resetSuggestions } = useAIResponse();
  const { generateReply } = useAIAutoReply();

  // Track processed items to avoid re-fetching
  const processingRef = useRef<Set<string>>(new Set());

  // Reactive Effect: Monitor history for new finalized items
  useEffect(() => {
    const lastItem = history[history.length - 1];

    // Only process if it's a FINAL item we haven't touched yet
    const processedKey = lastItem ? `${lastItem.id}:${lastItem.text}` : '';
    if (lastItem && lastItem.isFinal && !processingRef.current.has(processedKey)) {

      // Mark as processed
      processingRef.current.add(processedKey);

      // 1. Generate suggestions when the partner/AI speaks
      if (lastItem.sender === 'other') {
        generateSuggestions(lastItem.text, history);
      }

      // 2. Translate
      translateText(lastItem.text).then(translation => {
        updateHistory(lastItem.id, { translation });
      });

      // 3. Auto-reply only in Practice mode
      if (appMode === 'practice' && autoReplyEnabled && lastItem.sender === 'user') {
        generateReply(lastItem.text, history).then((reply) => {
          if (reply) addUtterance(reply, 'other');
        });
      }
    }
  }, [history, generateSuggestions, translateText, updateHistory, generateReply, addUtterance, appMode, autoReplyEnabled]);

  if (!appMode) {
    return <LandingPage onStart={(selectedMode) => {
      setAppMode(selectedMode);
      processingRef.current.clear();
      setAutoReplyEnabled(true);
      resetTranscript();
      resetSuggestions();
      setActiveSpeaker(selectedMode === 'practice' ? 'user' : 'other');
    }} />;
  }

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 font-sans selection:bg-primary/30 overflow-hidden relative">
      {/* Botão para voltar à Home */}
      <button 
        onClick={() => {
          if (isListening) stopListening();
          resetTranscript();
          resetSuggestions();
          setAppMode(null);
        }}
        className="fixed top-6 left-6 z-[100] flex items-center gap-2 px-4 py-2 bg-white/5 border border-white/10 rounded-full text-slate-400 hover:text-white hover:bg-white/10 transition-all active:scale-95"
      >
        <Home className="w-4 h-4" />
        <span className="text-sm font-medium">Voltar à Home</span>
      </button>

      {appMode === 'practice' && (
        <div className="fixed top-6 right-6 z-[100] flex items-center gap-3">
          <button
            onClick={() => setAutoReplyEnabled(v => !v)}
            className={cn(
              "px-3 py-2 border rounded-full text-xs font-semibold transition-all",
              autoReplyEnabled
                ? "bg-emerald-500/15 border-emerald-500/30 text-emerald-200 hover:bg-emerald-500/25"
                : "bg-white/5 border-white/10 text-slate-300 hover:bg-white/10"
            )}
          >
            {autoReplyEnabled ? 'Bot: ON' : 'Bot: OFF'}
          </button>
        </div>
      )}

      {/* Background Orbs */}
      <div className="fixed top-0 left-0 w-[500px] h-[500px] bg-primary/20 rounded-full blur-[120px] -translate-x-1/2 -translate-y-1/2 pointer-events-none" />
      <div className="fixed bottom-0 right-0 w-[500px] h-[500px] bg-blue-500/10 rounded-full blur-[120px] translate-x-1/2 translate-y-1/2 pointer-events-none" />
      {appMode === 'practice' && (
        <>
          <div className="fixed top-0 right-0 w-[620px] h-[620px] bg-[#0FB9B1]/15 rounded-full blur-[140px] translate-x-1/3 -translate-y-1/3 pointer-events-none" />
          <div className="fixed bottom-0 left-0 w-[620px] h-[620px] bg-[#0FB9B1]/10 rounded-full blur-[140px] -translate-x-1/3 translate-y-1/3 pointer-events-none" />
        </>
      )}

      {/* Main Content - Fixed Full Screen on Mobile */}
      <main className="flex flex-col md:flex-row relative z-10 w-full h-screen overflow-hidden">

        {/* Conversation Panel - Takes top 50% on mobile */}
        <section className="h-[50%] md:h-full flex-1 min-h-0 relative">
          <TranscriptionPanel
            history={history}
            currentInterim={currentInterim}
            onSwitchSpeaker={(id, currentSender) => {
              updateHistory(id, { sender: currentSender === 'user' ? 'other' : 'user' });
            }}
          />
        </section>

        {/* Brand Divider (Mobile Only) - Takes ~10% space visually */}
        <div className="shrink-0 flex justify-center items-center py-0 md:hidden opacity-40 pointer-events-none select-none z-50 -mt-10 mb-2">
          <Logo className="w-[85%] h-auto text-slate-300" />
        </div>

        {/* Suggestions Panel - Takes bottom 40% on mobile */}
        <section className="h-[40%] md:h-full shrink-0 md:w-1/3 flex flex-col min-h-0 z-20 bg-gradient-to-t from-black/90 via-slate-950/80 to-transparent md:bg-none pt-0">
          <div className="w-full h-full flex flex-col px-1 pb-1 pt-0 md:p-6">
            <SuggestionDock
              suggestions={suggestions}
              isLoading={isLoading}
                lastUserSpeech={[...history].reverse().find(h => h.sender === 'user' && h.isFinal)?.text}
              mode={mode}
              accent={appMode === 'practice' ? 'lino' : 'primary'}
              onSelect={(text) => addUtterance(text, 'user')}
              mobileTopRight={
                <div className="flex items-center gap-2">
                  <span className={cn(
                    "text-[10px] uppercase font-bold px-2 py-0.5 rounded-full border",
                    isTalkPressed
                      ? "bg-emerald-900/30 text-emerald-300 border-emerald-500/20"
                      : "bg-white/5 text-slate-300 border-white/10"
                  )}>
                    {isTalkPressed ? 'Falando' : 'Segure FALAR'}
                  </span>
                </div>
              }
            />

            {(appMode === 'live' || appMode === 'practice') && (
              <button
                onPointerDown={(e) => {
                  try {
                    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
                  } catch { }
                  setIsTalkPressed(true);
                  beginUserTalk();
                  if (!isListening) startListening();
                }}
                onPointerUp={(e) => {
                  try {
                    (e.currentTarget as HTMLElement).releasePointerCapture(e.pointerId);
                  } catch { }
                  setIsTalkPressed(false);
                  endUserTalk();
                }}
                onPointerCancel={(e) => {
                  try {
                    (e.currentTarget as HTMLElement).releasePointerCapture(e.pointerId);
                  } catch { }
                  setIsTalkPressed(false);
                  endUserTalk();
                }}
                className={cn(
                  "mt-4 md:mt-6 w-full rounded-2xl border text-center font-black tracking-widest select-none touch-none",
                  "py-6 md:py-5 text-3xl md:text-2xl transition-all active:scale-[0.99]",
                  appMode === 'practice' ? "border-[#0FB9B1]/35" : "border-white/10",
                  isTalkPressed
                    ? cn(
                      "text-emerald-100 shadow-[0_0_30px_rgba(16,185,129,0.15)]",
                      appMode === 'practice'
                        ? "bg-[#0FB9B1]/20 border-[#0FB9B1]/55"
                        : "bg-emerald-500/25 border-emerald-500/40"
                    )
                    : cn(
                      "bg-white/5 text-slate-200 hover:bg-white/10",
                      appMode === 'practice' ? "border-[#0FB9B1]/35" : "border-white/10"
                    )
                )}
              >
                FALAR
              </button>
            )}

            {/* PC Logo (Bottom Right) */}
            <div className="hidden md:flex justify-center items-center mt-auto pb-8 opacity-100">
              <Logo className="w-80 text-white drop-shadow-[0_0_15px_rgba(255,255,255,0.2)]" />
            </div>
          </div>
        </section>

      </main>
    </div>
  );
}

export default App;

import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import { cn } from '../lib/utils';
import type { Suggestion } from '../hooks/useAIResponse';

interface SuggestionDockProps {
    suggestions: Suggestion[];
    isLoading: boolean;
    onSelect?: (text: string) => void;
    lastUserSpeech?: string;
    mode?: 'native' | 'universal';
    mobileTopRight?: React.ReactNode;
    accent?: 'primary' | 'lino';
}

export const SuggestionDock: React.FC<SuggestionDockProps> = ({ suggestions, isLoading, onSelect, lastUserSpeech, mode, mobileTopRight, accent = 'primary' }) => {
    // ... existing hook logic ... 
    // We maintain a history of previous suggestion sets
    const [stack, setStack] = useState<Suggestion[][]>([]);
    const [highlightIndex, setHighlightIndex] = useState(-1);

    const STOPWORDS = new Set([
        "a", "an", "and", "are", "as", "at", "be", "been", "but", "by", "can", "could", "did", "do", "does",
        "for", "from", "get", "got", "had", "has", "have", "how", "i", "im", "in", "into", "is", "it", "just",
        "like", "me", "my", "no", "not", "of", "on", "or", "so", "that", "the", "their", "them", "then", "there",
        "these", "they", "this", "to", "up", "was", "we", "were", "what", "when", "where", "who", "why", "with",
        "you", "your"
    ]);

    const ALWAYS_IMPORTANT = new Set([
        "ok", "okay", "yes", "no", "hi", "hey", "bye", "thanks", "thank", "please", "sorry", "yeah", "nah", "dont", "wont"
    ]);

    const normalizeToken = (t: string) => {
        const map: Record<string, string> = {
            "thx": "thanks",
            "pls": "please",
            "plz": "please",
            "u": "you",
            "ur": "your",
            "r": "are",
            "im": "i",
            "ive": "i",
            "id": "i"
        };
        return map[t] ?? t;
    };

    const cleanText = (s: string) => s.toLowerCase()
        .replace(/[\u2018\u2019]/g, "'")
        .replace(/[.,/#!$%^&*;:{}=\-_`~()]/g, "")
        .replace(/['"]/g, "")
        .replace(/\s{2,}/g, " ")
        .trim();

    const tokenizeForMatch = (s: string) => {
        const tokens = cleanText(s)
            .split(/\s+/)
            .map(t => t.trim())
            .map(normalizeToken)
            .filter(Boolean)
            .filter(t => t.length >= 2)
            .filter(t => ALWAYS_IMPORTANT.has(t) || !STOPWORDS.has(t));
        return tokens;
    };

    const tokenizeKeywords = (s: string) => {
        const tokens = cleanText(s)
            .split(/\s+/)
            .map(t => t.trim())
            .map(normalizeToken)
            .filter(Boolean)
            .filter(t => ALWAYS_IMPORTANT.has(t) || t.length >= 4)
            .filter(t => ALWAYS_IMPORTANT.has(t) || !STOPWORDS.has(t));
        return tokens;
    };

    const diceCoefficient = (a: string, b: string) => {
        const s = a.replace(/\s+/g, '');
        const u = b.replace(/\s+/g, '');
        if (!s || !u) return 0;
        if (s === u) return 1;
        if (s.length < 2 || u.length < 2) return 0;
        const getBigrams = (str: string) => {
            const bg = new Map<string, number>();
            for (let i = 0; i < str.length - 1; i++) {
                const key = str.substring(i, i + 2);
                bg.set(key, (bg.get(key) ?? 0) + 1);
            }
            return bg;
        };
        const sBg = getBigrams(s);
        const uBg = getBigrams(u);
        let intersection = 0;
        for (const [k, v] of sBg.entries()) {
            const uCount = uBg.get(k) ?? 0;
            intersection += Math.min(v, uCount);
        }
        const total = Array.from(sBg.values()).reduce((acc, v) => acc + v, 0) + Array.from(uBg.values()).reduce((acc, v) => acc + v, 0);
        return total > 0 ? (2 * intersection) / total : 0;
    };

    useEffect(() => {
        if (suggestions.length > 0) {
            setStack(prev => {
                const newStack = [suggestions, ...prev];
                return newStack.slice(0, 2); // Keep current + 1 previous set
            });
        }
    }, [suggestions]);

    const currentSet = stack[0] || [];
    const previousSet = stack[1] || [];

    // Calculate highlighting whenever data changes
    useEffect(() => {
        if (!lastUserSpeech || previousSet.length === 0) {
            setHighlightIndex(-1);
            return;
        }

        const getMatchScore = (suggestion: string) => {
            const sClean = cleanText(suggestion);
            const uClean = cleanText(lastUserSpeech);
            if (!sClean || !uClean) return 0;
            if (sClean === uClean) return 1.0;

            const sTokens = new Set(tokenizeForMatch(suggestion));
            const uTokens = new Set(tokenizeForMatch(lastUserSpeech));

            const charScore = diceCoefficient(sClean, uClean);

            if (sTokens.size === 0 || uTokens.size === 0) return charScore;

            let intersection = 0;
            uTokens.forEach(token => { if (sTokens.has(token)) intersection++; });
            const precision = sTokens.size > 0 ? intersection / sTokens.size : 0;
            const recall = uTokens.size > 0 ? intersection / uTokens.size : 0;
            const f1 = (precision + recall) > 0 ? (2 * precision * recall) / (precision + recall) : 0;

            const combined = Math.max(f1, charScore * 0.85);
            if (sClean.includes(uClean) || uClean.includes(sClean)) return Math.max(combined, 0.95);
            return combined;
        };

        let bestIdx = -1;
        let highest = 0;

        previousSet.forEach((item, idx) => {
            const score = getMatchScore(item.en);
            if (score > highest) {
                highest = score;
                bestIdx = idx;
            }
        });

        setHighlightIndex(highest >= 0.25 ? bestIdx : -1);

    }, [lastUserSpeech, previousSet]);

    // Word highlighting renderer
    const renderHighlightedText = (text: string) => {
        if (!lastUserSpeech) return <>{text}</>;
        const userWords = new Set(tokenizeKeywords(lastUserSpeech));

        return text.split(' ').map((word, i) => {
            const cleanWord = normalizeToken(cleanText(word));
            const isImportant = ALWAYS_IMPORTANT.has(cleanWord) || (cleanWord.length >= 4 && !STOPWORDS.has(cleanWord));
            const isHit = isImportant && userWords.has(cleanWord);

            return (
                <span
                    key={i}
                    className={
                        isHit
                            ? "text-yellow-400 font-bold"
                            : isImportant
                                ? "text-red-400 opacity-80"
                                : "text-slate-400"
                    }
                >
                    {word}{" "}
                </span>
            );
        });
    };

    return (
        <div className="w-full flex flex-col gap-4 min-h-[120px]">
            <div className="flex justify-end pr-2">
                {mobileTopRight ? (
                    <div className="md:hidden">{mobileTopRight}</div>
                ) : (
                    mode && (
                        <span className={cn("text-[10px] uppercase font-bold px-2 py-0.5 rounded-full border",
                            mode === 'native' ? "bg-green-900/40 text-green-400 border-green-500/20" : "bg-blue-900/40 text-blue-400 border-blue-500/20"
                        )}>
                            {mode === 'native' ? '⚡ Native' : '🌐 Universal'}
                        </span>
                    )
                )}
            </div>

            {/* 1. CURRENT Suggestions (Active - Top) */}
            <div className="grid gap-3 grid-cols-1 w-full relative z-20">
                {isLoading ? (
                    [1, 2].map((i) => (
                        <div key={i} className="h-20 rounded-xl glass-card animate-pulse bg-white/5" />
                    ))
                ) : (
                    currentSet.length > 0 ? (
                        currentSet.slice(0, 2).map((item, idx) => (
                            <motion.button
                                key={`curr-${idx}-${item.en}`}
                                initial={{ opacity: 0, scale: 0.95 }}
                                animate={{ opacity: 1, scale: 1 }}
                                onClick={() => onSelect?.(item.en)}
                                className={cn(
                                    "text-left p-4 rounded-xl glass-card border-l-4 shadow-lg",
                                    "hover:bg-white/10 transition-all duration-300",
                                    accent === 'lino'
                                        ? "border-[#0FB9B1]/25 border-l-[#0FB9B1]/70 hover:border-l-[#0FB9B1]"
                                        : "border-l-primary/50 hover:border-l-primary",
                                    "group flex flex-col items-start gap-1 w-full"
                                )}
                            >
                                <span className="text-lg text-slate-100 font-semibold leading-tight">{item.en}</span>
                                <span className="text-sm text-blue-300/80 italic font-light">{item.pt}</span>
                            </motion.button>
                        ))
                    ) : (
                        <div className={cn(
                            "h-40 flex items-center justify-center text-slate-500 italic border border-dashed rounded-xl",
                            accent === 'lino' ? "border-[#0FB9B1]/25" : "border-white/10"
                        )}>
                            Aguardando contexto...
                        </div>
                    )
                )}
            </div>

            {/* 2. PREVIOUS Suggestions (History - Bottom) */}
            <div className="hidden md:flex items-end gap-3 px-1 mt-2">
                <div className="flex-1 flex flex-col gap-2 opacity-80">
                    {previousSet.length > 0 ? (
                        previousSet.slice(0, 2).map((item, idx) => {
                            const isWinner = idx === highlightIndex;
                            return (
                                <div
                                    key={`prev-${idx}`}
                                    data-speech={lastUserSpeech}
                                    className={cn(
                                        "p-3 border-b rounded-lg transition-colors duration-500",
                                        isWinner
                                            ? "bg-yellow-900/20 border-yellow-500/30 shadow-[0_0_10px_rgba(234,179,8,0.1)]"
                                            : cn("bg-black/20", accent === 'lino' ? "border-[#0FB9B1]/15" : "border-white/5")
                                    )}
                                >
                                    <p className={cn(
                                        "text-sm font-medium leading-snug transition-colors",
                                        !isWinner && "text-slate-400"
                                    )}>
                                        {isWinner ? renderHighlightedText(item.en) : item.en}
                                    </p>
                                    <p className="text-xs text-slate-600 italic leading-snug mt-0.5">{item.pt}</p>
                                </div>
                            );
                        })
                    ) : (
                        <div className="h-10" />
                    )}
                </div>
            </div>
        </div>
    );
};

import { useCallback, useState } from 'react';

export const useAIAutoReply = () => {
  const [isReplying, setIsReplying] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const generateReply = useCallback(async (userText: string, history: any[]) => {
    const cleaned = (userText ?? '').trim();
    if (!cleaned) return null;

    setIsReplying(true);
    setError(null);

    try {
      const recentHistory = history
        .slice(-10)
        .map((h: any) => `${h.sender === 'user' ? 'User' : 'Partner'}: ${h.text}`)
        .join('\n');

      const messages = [
        {
          role: 'system',
          content:
            'You are a helpful, natural conversation partner.\n' +
            'Reply to the User in English only.\n' +
            'Keep it very short: 1 sentence, max 14 words.\n' +
            'Optional: add 1 very short follow-up question (max 7 words).\n' +
            'Do not mention being an AI and do not write lists.'
        },
        {
          role: 'user',
          content: `Conversation so far:\n${recentHistory}\n\nUser just said: "${cleaned}"`
        }
      ];

      const response = await fetch('/api/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ messages, temperature: 0.7, max_tokens: 70 })
      });

      if (!response.ok) throw new Error('API Request Failed');

      const data = await response.json();
      const content = data?.choices?.[0]?.message?.content;
      if (!content) return null;

      return String(content).replace(/```/g, '').trim();
    } catch (e) {
      setError('Failed to generate reply');
      return null;
    } finally {
      setIsReplying(false);
    }
  }, []);

  return { generateReply, isReplying, error };
};

import { useState, useCallback } from 'react';

export interface Suggestion {
    en: string;
    pt: string;
}

export const useAIResponse = () => {
    const [suggestions, setSuggestions] = useState<Suggestion[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const resetSuggestions = useCallback(() => {
        setSuggestions([]);
        setIsLoading(false);
        setError(null);
    }, []);

    const generateSuggestions = useCallback(async (currentText: string, history: any[]) => {
        // Reduced threshold for context generation
        if (!currentText || currentText.length < 2) return;

        setIsLoading(true);
        setError(null);

        // Build conversation context (Last 6 messages)
        const recentHistory = history.slice(-6).map(h =>
            `${h.sender === 'user' ? 'Me' : 'Partner'}: ${h.text}`
        ).join('\n');

        const fullContext = `Conversation History:\n${recentHistory}\n Partner just said: "${currentText}"`;

        try {
            // Calculate context
            const now = new Date();
            const dateContext = now.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
            const timeContext = now.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });

            const messages = [
                {
                    role: "system",
                    content: `You are a conversation coach.
                    Current Real-time Context: Today is ${dateContext}, ${timeContext}.

                    TASK:
                    1. Analyze the Conversation History below.
                    2. Suggest 2 distinct, natural responses for the User to say NEXT.
                    3. If the conversation seems to have ended or there is a lull, make ONE of the 2 suggestions a NEW topic (e.g., "What's your favorite hobby?", "Have you traveled recently?").
                    4. Ensure suggestions follow the established context.

                    CONSTRAINTS (IMPORTANT):
                    - Each EN suggestion: 1 sentence, max 9 words, max 60 characters.
                    - Each PT suggestion: 1 sentence, max 9 words, max 70 characters.
                    - Prefer short, natural, spoken replies. No explanations.
                    - Avoid multiple questions; at most 1 short question total across both suggestions.
                    - No emojis. No quotes around the sentence text.

                    FORMAT:
                    You must return a raw JSON array. No markdown formatting.
                    Example:
                    [
                        {"en": "Where to?", "pt": "Para onde?"},
                        {"en": "What do you do for fun?", "pt": "O que você faz para se divertir?"}
                    ]

                    Strictly valid JSON only.`
                },
                {
                    role: "user",
                    content: fullContext
                }
            ];

            const response = await fetch('/api/chat', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({ messages, temperature: 0.4, max_tokens: 90 })
            });

            if (!response.ok) throw new Error('API Request Failed');

            const data = await response.json();

            if (data.choices && data.choices.length > 0) {
                let content = data.choices[0].message.content;
                // Clean up markdown code blocks if present
                content = content.replace(/```json/g, '').replace(/```/g, '').trim();

                try {
                    const parsed = JSON.parse(content);
                    if (Array.isArray(parsed)) {
                        const newSuggestions = parsed.slice(0, 2).map((item: any) => ({
                            en: item.en || "Error",
                            pt: item.pt || "..."
                        }));
                        setSuggestions(newSuggestions);
                    }
                } catch (e) {
                    console.error("Failed to parse AI suggestions JSON", e);
                    // Fallback
                    setSuggestions([
                        { en: "I see.", pt: "Entendo." },
                        { en: "Go on.", pt: "Continue." }
                    ]);
                }
            }

        } catch (err) {
            console.error(err);
            setError('Failed to fetch suggestions');
            setSuggestions([
                { en: "I didn't catch that.", pt: "Não entendi." },
                { en: "Can you repeat?", pt: "Pode repetir?" }
            ]);
        } finally {
            setIsLoading(false);
        }
    }, []);

    return { suggestions, isLoading, error, generateSuggestions, resetSuggestions };
};

import { useState, useRef, useCallback } from 'react';

export const useAudioRecorder = () => {
    const [isRecording, setIsRecording] = useState(false);
    const mediaRecorder = useRef<MediaRecorder | null>(null);
    const streamRef = useRef<MediaStream | null>(null);
    const chunks = useRef<Blob[]>([]);
    const audioContextRef = useRef<AudioContext | null>(null);
    const analyserRef = useRef<AnalyserNode | null>(null);
    const maxRmsRef = useRef<number>(0);
    const currentRmsRef = useRef<number>(0);
    const rafRef = useRef<number | null>(null);
    const mimeTypeRef = useRef<string>('audio/webm');

    const startRecording = useCallback(async () => {
        try {
            // Mantém o stream aberto para evitar que o ícone do microfone pisque
            if (!streamRef.current || !streamRef.current.active) {
                streamRef.current = await navigator.mediaDevices.getUserMedia({
                    audio: {
                        echoCancellation: true,
                        noiseSuppression: true,
                        autoGainControl: true,
                        channelCount: 1
                    }
                });
            }

            if (!audioContextRef.current) {
                audioContextRef.current = new AudioContext();
            }
            if (audioContextRef.current.state === 'suspended') {
                try { await audioContextRef.current.resume(); } catch { }
            }

            if (!analyserRef.current) {
                const ctx = audioContextRef.current;
                const source = ctx.createMediaStreamSource(streamRef.current);
                const analyser = ctx.createAnalyser();
                analyser.fftSize = 2048;
                source.connect(analyser);
                analyserRef.current = analyser;
            }

            maxRmsRef.current = 0;
            currentRmsRef.current = 0;

            if (rafRef.current) {
                cancelAnimationFrame(rafRef.current);
                rafRef.current = null;
            }

            const measure = () => {
                const analyser = analyserRef.current;
                const recorder = mediaRecorder.current;
                if (!analyser || !recorder || recorder.state !== 'recording') return;

                const buffer = new Uint8Array(analyser.fftSize);
                analyser.getByteTimeDomainData(buffer);

                let sumSquares = 0;
                for (let i = 0; i < buffer.length; i++) {
                    const v = (buffer[i] - 128) / 128;
                    sumSquares += v * v;
                }
                const rms = Math.sqrt(sumSquares / buffer.length);
                currentRmsRef.current = rms;
                if (rms > maxRmsRef.current) maxRmsRef.current = rms;

                rafRef.current = requestAnimationFrame(measure);
            };

            if (mediaRecorder.current && mediaRecorder.current.state === 'recording') {
                setIsRecording(true);
                rafRef.current = requestAnimationFrame(measure);
                return;
            }

            mediaRecorder.current = new MediaRecorder(streamRef.current);
            mimeTypeRef.current = (mediaRecorder.current.mimeType || 'audio/webm').split(';')[0].trim() || 'audio/webm';
            chunks.current = [];

            mediaRecorder.current.ondataavailable = (e) => {
                if (e.data.size > 0) {
                    chunks.current.push(e.data);
                }
            };

            mediaRecorder.current.start();
            setIsRecording(true);
            rafRef.current = requestAnimationFrame(measure);
        } catch (err) {
            console.error("Mic access denied or not supported", err);
        }
    }, []);

    const stopRecording = useCallback(async (shouldStopStream = false): Promise<{ blob: Blob | null; maxRms: number; mimeType: string }> => {
        return new Promise((resolve) => {
            if (!mediaRecorder.current || mediaRecorder.current.state === 'inactive') {
                if (shouldStopStream && streamRef.current) {
                    streamRef.current.getTracks().forEach(track => track.stop());
                    streamRef.current = null;

                    if (analyserRef.current) {
                        try { analyserRef.current.disconnect(); } catch { }
                        analyserRef.current = null;
                    }

                    if (audioContextRef.current) {
                        audioContextRef.current.close().catch(() => undefined);
                        audioContextRef.current = null;
                    }
                }

                if (rafRef.current) {
                    cancelAnimationFrame(rafRef.current);
                    rafRef.current = null;
                }

                setIsRecording(false);
                return resolve({ blob: null, maxRms: 0, mimeType: mimeTypeRef.current });
            }

            mediaRecorder.current.onstop = () => {
                const mimeType = mimeTypeRef.current || 'audio/webm';
                const blob = new Blob(chunks.current, { type: mimeType });
                const maxRms = maxRmsRef.current;
                chunks.current = [];
                setIsRecording(false);

                if (rafRef.current) {
                    cancelAnimationFrame(rafRef.current);
                    rafRef.current = null;
                }

                if (shouldStopStream && streamRef.current) {
                    streamRef.current.getTracks().forEach(track => track.stop());
                    streamRef.current = null;

                    if (analyserRef.current) {
                        try { analyserRef.current.disconnect(); } catch { }
                        analyserRef.current = null;
                    }

                    if (audioContextRef.current) {
                        audioContextRef.current.close().catch(() => undefined);
                        audioContextRef.current = null;
                    }
                }

                resolve({ blob, maxRms, mimeType });
            };

            mediaRecorder.current.stop();
        });
    }, []);

    return {
        isRecording,
        startRecording,
        stopRecording,
        getCurrentRms: () => currentRmsRef.current,
        isSupported: !!(navigator.mediaDevices && navigator.mediaDevices.getUserMedia)
    };
};

import { useState, useCallback, useRef } from 'react';
import { useAudioRecorder } from './useAudioRecorder';

export interface Utterance {
    id: string;
    text: string;
    translation?: string;
    timestamp: number;
    isFinal: boolean;
    sender?: 'user' | 'other';
}

export interface SpeechRecognitionHook {
    isListening: boolean;
    currentInterim: string;
    history: Utterance[];
    activeSpeaker: 'user' | 'other';
    setActiveSpeaker: (speaker: 'user' | 'other') => void;
    switchSpeaker: (speaker: 'user' | 'other') => void;
    beginUserTalk: () => void;
    endUserTalk: () => void;
    startListening: () => void;
    stopListening: () => void;
    resetTranscript: () => void;
    addUtterance: (text: string, sender: 'user' | 'other') => void;
    browserSupportsSpeechRecognition: boolean;
    updateHistory: (id: string, updates: Partial<Utterance>) => void;
    mode: 'native' | 'universal';
}

export const useSpeechRecognition = (options?: { sessionMode?: 'live' | 'practice' }): SpeechRecognitionHook => {

    // --- State ---
    const [isListening, setIsListening] = useState(false);
    const [currentInterim, setCurrentInterim] = useState('');
    const [history, setHistory] = useState<Utterance[]>([]);
    const [activeSpeaker, setActiveSpeakerState] = useState<'user' | 'other'>('other');

    // --- Refs ---
    const isListeningRef = useRef(false);
    const lastUtteranceTime = useRef<number>(Date.now());
    const isPolyfillLoopActive = useRef(false);
    const activeSpeakerRef = useRef<'user' | 'other'>('other');
    const inFlightTranscribesRef = useRef<Set<AbortController>>(new Set());
    const chunkWaitAbortRef = useRef<AbortController | null>(null);
    const CHUNK_MS = 1200;
    const USER_PAUSE_TOLERANCE_MS = 2000;
    const USER_MAX_HOLD_MS = 5 * 60 * 1000;
    const isPushToTalkActiveRef = useRef(false);
    const userReleaseAbortTimerRef = useRef<number | null>(null);
    const practiceFinalizeTimerRef = useRef<number | null>(null);
    const practiceDraftRef = useRef<string>('');
    const stopAfterThisChunkRef = useRef(false);

    const sessionMode: 'live' | 'practice' = options?.sessionMode ?? 'live';

    const setActiveSpeaker = useCallback((speaker: 'user' | 'other') => {
        activeSpeakerRef.current = speaker;
        setActiveSpeakerState(speaker);
    }, []);

    // --- Polyfill Logic (OpenAI Whisper) ---
    const { startRecording, stopRecording, isSupported: hasMicSupport } = useAudioRecorder();

    // --- Ultimate Hallucination Filter ---
    const isHallucination = (text: string): boolean => {
        const cleaned = text.trim().toLowerCase();

        // 1. Check for ANY non-Latin/Asian characters
        const hasAsianChars = /[\u3040-\u30ff\u3400-\u4dbf\u4e00-\u9fff\uf900-\ufaff\uff66-\uff9f\uac00-\ud7af]/.test(text);
        if (hasAsianChars) return true;

        // 2. Strict blacklist
        const blacklisted = [
            "thank you for watching",
            "thanks for watching",
            "please subscribe",
            "subtitles by",
            "mbc news",
            "mbc 뉴스",
            "bye bye",
            "you",
            "you.",
            "bye.",
            "hello."
        ];
        if (blacklisted.some(phrase => cleaned === phrase || cleaned.includes(phrase))) return true;

        // 3. Latin-only Regex (Strict)
        const latinOnlyRegex = /^[a-zA-Z0-9\s.,!?;:'"()\-áàâãéèêíïóôõöúçÁÀÂÃÉÈÊÍÏÓÔÕÖÚÇ]*$/;
        if (!latinOnlyRegex.test(text)) return true;

        // 4. Noise Filter (Too short or just punctuation)
        if (cleaned.length < 2) return true;
        if (/^[.,!?\s]+$/.test(cleaned)) return true;

        return false;
    };

    // --- Helper: Add Text to History ---
    const addTextToHistory = useCallback((text: string, senderOverride?: 'user' | 'other') => {
        if (!text || isHallucination(text)) return;

        const cleanedText = text.trim();
        const senderCandidate = senderOverride ?? activeSpeakerRef.current;
        if (senderCandidate === 'other') {
            const wordCount = cleanedText.split(/\s+/).filter(Boolean).length;
            if (cleanedText.length < 8 || wordCount < 2) return;
        }

        const now = Date.now();
        const timeSinceLast = now - lastUtteranceTime.current;
        const sender = senderCandidate;

        lastUtteranceTime.current = now;

        setHistory(prev => {
            const lastItem = prev[prev.length - 1];

            if (lastItem && lastItem.sender === sender && timeSinceLast < 2500) {
                return prev.map((item, idx) => {
                    if (idx === prev.length - 1) {
                        return { ...item, text: item.text + " " + text, timestamp: now, translation: undefined };
                    }
                    return item;
                });
            }

            const newId = Date.now().toString() + Math.random().toString().slice(2, 5);
            return [...prev, {
                id: newId,
                text: text,
                timestamp: now,
                isFinal: true,
                sender
            }];
        });
    }, [sessionMode]);

    const addUtterance = useCallback((text: string, sender: 'user' | 'other') => {
        const cleaned = text.trim();
        if (!cleaned) return;

        const now = Date.now();
        const newId = Date.now().toString() + Math.random().toString().slice(2, 5);
        lastUtteranceTime.current = now;

        setHistory(prev => [...prev, {
            id: newId,
            text: cleaned,
            timestamp: now,
            isFinal: true,
            sender
        }]);
    }, []);

    const appendPracticeDraft = useCallback((text: string) => {
        const cleaned = text.trim();
        if (!cleaned) return;

        practiceDraftRef.current = practiceDraftRef.current
            ? `${practiceDraftRef.current} ${cleaned}`
            : cleaned;

        setCurrentInterim(practiceDraftRef.current);

        if (practiceFinalizeTimerRef.current) {
            clearTimeout(practiceFinalizeTimerRef.current);
            practiceFinalizeTimerRef.current = null;
        }

        practiceFinalizeTimerRef.current = window.setTimeout(() => {
            const finalText = practiceDraftRef.current.trim();
            if (!finalText) return;
            practiceDraftRef.current = '';
            setCurrentInterim('');
            addUtterance(finalText, 'user');
        }, USER_PAUSE_TOLERANCE_MS);
    }, [addUtterance]);

    const finalizePracticeDraft = useCallback(() => {
        const finalText = practiceDraftRef.current.trim();
        if (!finalText) return;
        practiceDraftRef.current = '';
        setCurrentInterim('');
        addUtterance(finalText, 'user');
    }, [addUtterance]);

    // --- Transcription Logic ---
    const transcribeBlob = useCallback(async (blob: Blob, senderForChunk: 'user' | 'other') => {
        try {
            const reader = new FileReader();
            reader.onloadend = async () => {
                const controller = new AbortController();
                inFlightTranscribesRef.current.add(controller);

                try {
                    const base64Audio = (reader.result as string).split(',')[1];
                    const response = await fetch('/api/transcribe', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ audio: base64Audio, mimeType: blob.type }),
                        signal: controller.signal
                    });

                    if (response.ok) {
                        const data = await response.json();
                        if (data && data.text) {
                            if (sessionMode === 'practice' && senderForChunk === 'user') {
                                appendPracticeDraft(data.text);
                            } else {
                                addTextToHistory(data.text, senderForChunk);
                            }
                        }
                    }
                } catch (e: any) {
                    if (e?.name !== 'AbortError') {
                        console.error("Transcribe request failed:", e);
                    }
                } finally {
                    inFlightTranscribesRef.current.delete(controller);
                }
            };
            reader.readAsDataURL(blob);
        } catch (e) {
            console.error("Transcription failed:", e);
        }
    }, [addTextToHistory, appendPracticeDraft, sessionMode]);

    const runPolyfillLoop = useCallback(async () => {
        if (!isPolyfillLoopActive.current) return;
        try {
            const senderForChunk = activeSpeakerRef.current;
            await startRecording();
            setIsListening(true);
            if (!(sessionMode === 'practice' && senderForChunk === 'user')) {
                setCurrentInterim("Listening...");
            }

            const chunkAbort = new AbortController();
            chunkWaitAbortRef.current?.abort();
            chunkWaitAbortRef.current = chunkAbort;

            await new Promise<void>((resolve) => {
                const shouldHoldForPushToTalk =
                    senderForChunk === 'user' &&
                    isPushToTalkActiveRef.current &&
                    (sessionMode === 'live' || sessionMode === 'practice');
                const waitMs = shouldHoldForPushToTalk ? USER_MAX_HOLD_MS : CHUNK_MS;
                const t = setTimeout(resolve, waitMs);
                chunkAbort.signal.addEventListener('abort', () => {
                    clearTimeout(t);
                    resolve();
                }, { once: true });
            });

            if (!isPolyfillLoopActive.current) {
                await stopRecording(true);
                setIsListening(false);
                return;
            }

            if (!(sessionMode === 'practice' && senderForChunk === 'user')) {
                setCurrentInterim("Thinking...");
            }
            const { blob, maxRms } = await stopRecording(false);

            const VAD_RMS_THRESHOLD = senderForChunk === 'other' ? 0.028 : 0.009;
            const MIN_BLOB_SIZE = senderForChunk === 'other' ? 2200 : 300;
            if (blob && blob.size > MIN_BLOB_SIZE && maxRms >= VAD_RMS_THRESHOLD) {
                transcribeBlob(blob, senderForChunk);
            }
            if (!(sessionMode === 'practice' && senderForChunk === 'user')) {
                setCurrentInterim("");
            }

            if (stopAfterThisChunkRef.current) {
                stopAfterThisChunkRef.current = false;
                isPolyfillLoopActive.current = false;
                await stopRecording(true);
                setIsListening(false);
                setCurrentInterim("");
                return;
            }

            if (isPolyfillLoopActive.current) runPolyfillLoop();
        } catch (error) {
            console.error("Loop Error:", error);
            setIsListening(false);
            isPolyfillLoopActive.current = false;
        }
    }, [CHUNK_MS, sessionMode, startRecording, stopRecording, transcribeBlob]);

    // --- External Controls ---
    const startListening = useCallback(() => {
        console.log("Start Listening (Whisper Only)");
        isListeningRef.current = true;
        if (hasMicSupport) {
            if (isPolyfillLoopActive.current) return;
            if (sessionMode === 'practice') {
                setActiveSpeaker('user');
                practiceDraftRef.current = '';
                if (practiceFinalizeTimerRef.current) {
                    clearTimeout(practiceFinalizeTimerRef.current);
                    practiceFinalizeTimerRef.current = null;
                }
                setCurrentInterim('');
            }
            isPolyfillLoopActive.current = true;
            runPolyfillLoop();
        }
    }, [hasMicSupport, runPolyfillLoop, sessionMode, setActiveSpeaker]);

    const beginUserTalk = useCallback(() => {
        setActiveSpeaker('user');
        isPushToTalkActiveRef.current = true;
        stopAfterThisChunkRef.current = false;
        if (userReleaseAbortTimerRef.current) {
            clearTimeout(userReleaseAbortTimerRef.current);
            userReleaseAbortTimerRef.current = null;
        }
    }, [setActiveSpeaker]);

    const endUserTalk = useCallback(() => {
        isPushToTalkActiveRef.current = false;
        setActiveSpeaker('other');
        stopAfterThisChunkRef.current = true;
        chunkWaitAbortRef.current?.abort();
    }, [setActiveSpeaker]);

    const switchSpeaker = useCallback((speaker: 'user' | 'other') => {
        if (sessionMode === 'practice') return;
        setActiveSpeaker(speaker);
        if (speaker === 'user') {
            isPushToTalkActiveRef.current = true;
            if (userReleaseAbortTimerRef.current) {
                clearTimeout(userReleaseAbortTimerRef.current);
                userReleaseAbortTimerRef.current = null;
            }
            chunkWaitAbortRef.current?.abort();
            return;
        }

        isPushToTalkActiveRef.current = false;
        if (userReleaseAbortTimerRef.current) {
            clearTimeout(userReleaseAbortTimerRef.current);
            userReleaseAbortTimerRef.current = null;
        }
        userReleaseAbortTimerRef.current = window.setTimeout(() => {
            if (isPushToTalkActiveRef.current) return;
            chunkWaitAbortRef.current?.abort();
        }, USER_PAUSE_TOLERANCE_MS);
    }, [setActiveSpeaker, sessionMode]);

    const stopListening = useCallback(() => {
        console.log("Stop Listening");
        isListeningRef.current = false;
        isPolyfillLoopActive.current = false;
        chunkWaitAbortRef.current?.abort();
        chunkWaitAbortRef.current = null;
        if (userReleaseAbortTimerRef.current) {
            clearTimeout(userReleaseAbortTimerRef.current);
            userReleaseAbortTimerRef.current = null;
        }
        if (practiceFinalizeTimerRef.current) {
            clearTimeout(practiceFinalizeTimerRef.current);
            practiceFinalizeTimerRef.current = null;
        }
        if (sessionMode === 'practice') {
            finalizePracticeDraft();
        }
        inFlightTranscribesRef.current.forEach(c => c.abort());
        inFlightTranscribesRef.current.clear();

        stopRecording(true).then(() => {
            setIsListening(false);
            setCurrentInterim("");
        });
    }, [finalizePracticeDraft, sessionMode, stopRecording]);

    return {
        isListening,
        currentInterim,
        history,
        activeSpeaker,
        setActiveSpeaker,
        switchSpeaker,
        beginUserTalk,
        endUserTalk,
        startListening,
        stopListening,
        resetTranscript: () => setHistory([]),
        addUtterance,
        browserSupportsSpeechRecognition: true,
        updateHistory: (id, updates) => setHistory(p => p.map(i => i.id === id ? { ...i, ...updates } : i)),
        mode: 'universal'
    };
};

